sketch:
// Button — a pushbutton on pin 2 lights the built-in LED while it is held.
//
// Pin 2 uses the chip's own pull-up, so the button only needs wiring to ground:
// held, it reads LOW; released, the pull-up takes it back HIGH. That is why the
// test inverts it. Press and hold the button on the canvas to try it.

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_BUILTIN, digitalRead(2) == LOW);
}
